if (!msg._state_changed) return null;
const d = msg.device;
if (d.type !== 'ac_controller' && d.type !== 'mcb') return null;

const cfg = (global.get('device_configs') || {})[d.id] || {};
const ts = d.ts || new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Ho_Chi_Minh' }).replace(' ', 'T');
const deviceName = cfg.friendly_name || d.id;
const location = cfg.location || '';

const baseTopic = 'smarteos/bluCafe/' + d.type + '/' + d.id + '/';
const state = d.state || {};

function pub(attr, val, name, unit) {
    if (val === undefined || val === null) return;
    const payload = { ts: ts, value: val, name: name, device_name: deviceName, location: location };
    if (unit) payload.unit = unit;
    node.send({ topic: baseTopic + attr, payload: JSON.stringify(payload) });
}

if (d.type === 'ac_controller') {
    pub('power', state.power, 'Power Status');
    pub('temperature', state.temperature, 'Set Temperature', '°C');
    pub('fan_speed', state.fan_speed, 'Fan Speed');
    pub('ambient_temp', state.ambient_temp, 'Room Temperature', '°C');
    pub('online', state.online, 'Online Status');
    pub('link_quality', state.link_quality, 'Link Quality');
} else if (d.type === 'mcb') {
    pub('control', state.control, 'Relay Status');
    pub('temp', state.temp, 'Device Temperature', '°C');
    pub('current_power', state.meas_0276, 'Current Power', 'W');
    pub('current_energy', state.meas_0283, 'Current Energy', 'Wh');
    pub('current_ampe', state.meas_0272, 'Current Amperage', 'A');
    pub('rated_current', state.meas_0272, 'Rated Current', 'A');
    pub('high_voltage_cutoff', state.meas_0273, 'High Voltage Cutoff', 'V');
    pub('low_voltage_cutoff', state.meas_0274, 'Low Voltage Cutoff', 'V');
    pub('max_power', state.meas_0277, 'Max Power', 'W');
    pub('online', state.online, 'Online Status');
    pub('link_quality', state.link_quality, 'Link Quality');
}
return null;

const rows = msg.payload || [];
if (rows.length === 0) return null;

const configs = global.get('device_configs') || {};

const byDevice = {};
for (const r of rows) {
    if (!byDevice[r.device_id]) byDevice[r.device_id] = [];
    byDevice[r.device_id].push(r);
}

for (const [deviceId, deviceRows] of Object.entries(byDevice)) {
    const cfg = configs[deviceId] || {};
    const deviceName = cfg.friendly_name || deviceId;
    const location = cfg.location || '';
    const type = cfg.type || 'unknown';

    const latest = {};
    for (const r of deviceRows) {
        if (!latest[r.attr_name] || r.ts > latest[r.attr_name].ts) {
            latest[r.attr_name] = r;
        }
    }

    const baseTopic = 'smarteos/bluCafe/' + type + '/' + deviceId + '/';
    const ts = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Ho_Chi_Minh' }).replace(' ', 'T');

    function pub(attr, val, name, unit) {
        if (val === undefined || val === null) return;
        const payload = { ts: ts, value: val, name: name, device_name: deviceName, location: location };
        if (unit) payload.unit = unit;
        node.send({ topic: baseTopic + attr, payload: JSON.stringify(payload) });
    }

    for (const [attr, r] of Object.entries(latest)) {
        let val = r.attr_value;
        if (val === null) val = r.attr_str;
        if (val === null) continue;

        if (val === 'true') val = true;
        if (val === 'false') val = false;

        let name = attr;
        let unit = null;

        switch(attr) {
            case 'power': name = 'Power Status'; break;
            case 'temperature': name = 'Set Temperature'; unit = '°C'; break;
            case 'fan_speed': name = 'Fan Speed'; break;
            case 'ambient_temp': name = 'Room Temperature'; unit = '°C'; break;
            case 'control': name = 'Relay Status'; break;
            case 'temp': name = 'Device Temperature'; unit = '°C'; break;
            case 'meas_0276': name = 'Current Power'; unit = 'W'; break;
            case 'meas_0283': name = 'Current Energy'; unit = 'Wh'; break;
            case 'meas_0272': name = 'Current Amperage'; unit = 'A'; break;
            case 'meas_0273': name = 'High Voltage Cutoff'; unit = 'V'; break;
            case 'meas_0274': name = 'Low Voltage Cutoff'; unit = 'V'; break;
            case 'meas_0277': name = 'Max Power'; unit = 'W'; break;
            case 'online': name = 'Online Status'; break;
            case 'link_quality': name = 'Link Quality'; break;
        }

        pub(attr, val, name, unit);
    }
}
return null;
